import { z } from 'zod';

/**
 * Reusable validation building blocks. Feature schemas (later phases) compose these instead of
 * re-implementing format rules. The API validates every input with these schemas; the web app
 * may reuse them for instant form feedback, but the API remains the authority.
 */

/** Opaque record identifier (UUID, generated by the API). */
export const IdSchema = z.uuid({ message: 'Must be a valid identifier' });

/** Required text: trimmed, non-empty, bounded length. */
export function requiredText(max: number, label = 'Value') {
  return z
    .string({ message: `${label} is required` })
    .trim()
    .min(1, { message: `${label} is required` })
    .max(max, { message: `${label} must be at most ${max} characters` });
}

/** Optional text: trimmed; empty string becomes null. */
export function optionalText(max: number, label = 'Value') {
  return z
    .string()
    .trim()
    .max(max, { message: `${label} must be at most ${max} characters` })
    .nullish()
    .transform((value) => (value === undefined || value === '' ? null : value));
}

function isRealCalendarDate(value: string): boolean {
  const [y, m, d] = value.split('-').map(Number) as [number, number, number];
  const date = new Date(Date.UTC(y, m - 1, d));
  return date.getUTCFullYear() === y && date.getUTCMonth() === m - 1 && date.getUTCDate() === d;
}

/** Calendar date without time zone, 'YYYY-MM-DD' (attendance dates, academic year bounds). */
export const IsoDateSchema = z
  .string()
  .regex(/^\d{4}-\d{2}-\d{2}$/, { message: 'Must be a date in YYYY-MM-DD format' })
  .refine(isRealCalendarDate, { message: 'Must be a real calendar date' });

/** Time of day, 24-hour 'HH:MM' (period start/end). */
export const TimeOfDaySchema = z
  .string()
  .regex(/^([01]\d|2[0-3]):[0-5]\d$/, { message: 'Must be a time in HH:MM (24-hour) format' });

/** '#RRGGBB' colour. */
export const HexColorSchema = z
  .string()
  .regex(/^#[0-9a-fA-F]{6}$/, { message: 'Must be a colour in #RRGGBB format' })
  .transform((value) => value.toUpperCase());

/** Standard list pagination (query string values arrive as strings). */
export const PAGE_SIZE_DEFAULT = 25;
export const PAGE_SIZE_MAX = 100;
export const PaginationQuerySchema = z.object({
  page: z.coerce.number().int().min(1).default(1),
  pageSize: z.coerce.number().int().min(1).max(PAGE_SIZE_MAX).default(PAGE_SIZE_DEFAULT),
});
export type PaginationQuery = z.infer<typeof PaginationQuerySchema>;

/** A single validation problem in an API error response. */
export interface FieldIssue {
  /** Dot path to the offending field, e.g. "body.startDate". Empty for whole-input problems. */
  path: string;
  message: string;
}

/** Convert a Zod error into transport-safe issues, optionally prefixing the location (body/query/params). */
export function toFieldIssues(error: z.ZodError, location?: string): FieldIssue[] {
  return error.issues.map((issue) => {
    const path = issue.path.map(String).join('.');
    return {
      path: location ? (path ? `${location}.${path}` : location) : path,
      message: issue.message,
    };
  });
}
